// App and agent logos generated by scripts/logos.mjs (public/logos/index.json, public/agents/index.json). The index is
// re-read when it changes, so regenerating logos doesn't need a restart.
import fs from "node:fs";
import path from "node:path";
import { ROOT } from "../config.js";
import { html } from "./html.js";

function indexLoader(file) {
  let data = {};
  let version = null;
  return () => {
    const v = fs.existsSync(file) ? fs.statSync(file).mtimeMs : null;
    if (v !== version) {
      data = v ? JSON.parse(fs.readFileSync(file, "utf8")) : {};
      version = v;
    }
    return data;
  };
}

const appIndex = indexLoader(path.join(ROOT, "public", "logos", "index.json"));
const agentIndex = indexLoader(path.join(ROOT, "public", "agents", "index.json"));

/** Logo file URL and whether it is a full image (shown on a light tile) rather than an SVG tile. */
export function appLogoSrc(c) {
  const l = appIndex()[c.id];
  return { src: `/logos/${l?.file || "_generic.svg"}`, image: l?.kind === "image" };
}
export function agentLogoSrc(a) {
  const l = agentIndex()[a.id];
  return { src: `/agent-logos/${l?.file || "_generic.svg"}`, image: l?.kind === "image" };
}

const img = ({ src, image }, size, cls) => html`<img class="logo ${image ? "is-image" : ""} ${cls}" src="${src}" alt="" width="${size}" height="${size}" loading="lazy" decoding="async">`;
export const appLogo = (c, size = 40, cls = "") => img(appLogoSrc(c), size, cls);
export const agentLogo = (a, size = 40, cls = "") => img(agentLogoSrc(a), size, cls);
